// ─── CONFIGURACIÓN DEL LOTE ─────────────────────────────────────────────
// Ajusta aquí rutas, servicio de PDF y vigencias. Todo lo demás lo lee de este nodo.
const hoy = new Date();
const fechaLocal = new Date(hoy.getTime() - 5 * 3600 * 1000).toISOString().slice(0, 10); // America/Guayaquil (UTC-5)

return [{
  json: {
    BASE_DIR: '/data/expedientes',            // contiene postulantes.csv, entrada/<cedula>/ y salida/
    GOTENBERG_URL: 'http://gotenberg:3000',   // servicio de conversión/unión de PDF (ver docker-compose.yml)
    FECHA_PROCESO: fechaLocal,
    DIAS_POR_VENCER: 7,                       // alerta "próximo a vencer" si quedan <= N días
    ORGANIZACION: 'Expediente de reclutamiento — Guardias de seguridad',

    // Vigencias en días contadas desde la fecha de emisión. VALORES DE REFERENCIA:
    // confírmenlos con la política del cliente / requisitos del ente de control antes de usarlos.
    VIGENCIA_DIAS: {
      antecedentes: 30,
      judiciales: 30,
      no_ffaa: 90,
      clts: 90,
      servidor_publico: 30,
      titulo_bachiller: null,
      psicologico: 180,
      aptitud_fisica: 90,
      toxicologico: 30,
      cedula: null,          // la foto de la cédula no caduca por emisión (revisar fecha de expiración de la cédula a mano)
    },

    // Estado de los portales verificado el 25/11/2026. Por eso la descarga es asistida (humano + n8n).
    PORTALES: {
      antecedentes: {
        url: 'https://certificados.ministeriodelinterior.gob.ec/gestorcertificados/antecedentes/',
        bloqueo: 'Portal protegido por capa anti-bots (Imperva/Incapsula); formulario de 3 pasos con "motivo de consulta" (mín. 10 caracteres)',
        instruccion: 'Ecuatoriano: SÍ → Cédula → número → motivo "Proceso de reclutamiento de personal" → Visualizar Certificado → guardar PDF',
      },
      judiciales: {
        url: 'https://procesosjudiciales.funcionjudicial.gob.ec/busqueda-filtros',
        alterno: 'https://consultas.funcionjudicial.gob.ec/informacionjudicialindividual/pages/index.jsf#!/',
        bloqueo: 'Portal protegido por capa anti-bots (F5 TSPD) y no emite certificado: el PDF es la impresión de la consulta',
        instruccion: 'Cédula en "Demandado / Procesado" → BUSCAR → Imprimir (Ctrl+P) → Guardar como PDF (incluye fecha de consulta)',
      },
      no_ffaa: {
        url: 'https://sidehu.midena.gob.ec/certificados/nofa.action',
        bloqueo: 'Captcha de imagen ("Texto de Seguridad")',
        instruccion: 'Cédula + texto de seguridad → Consultar → descargar PDF',
      },
      clts: {
        url: 'https://sidehu.midena.gob.ec/certificados/clts.action',
        bloqueo: 'Captcha de imagen + pregunta de seguridad personal que solo puede responder el titular',
        instruccion: 'Cédula + texto de seguridad → pregunta de seguridad (con el postulante presente) → imprimir certificado en PDF',
      },
      servidor_publico: {
        url: 'https://calculadoras.trabajo.gob.ec/dependencia',
        bloqueo: 'Google reCAPTCHA y requiere fecha de nacimiento',
        instruccion: 'Número de documento + fecha de nacimiento (DD/MM/AAAA) → Generar → guardar PDF',
      },
      titulo_bachiller: {
        url: 'https://servicios.educacion.gob.ec/titulacion25-web/faces/paginas/consulta-titulos-refrendados.xhtml',
        bloqueo: 'Captcha de imagen en portal del Ministerio de Educación',
        instruccion: 'Cédula en Búsqueda por Cédula + código de imagen → Buscar → Imprimir/Guardar PDF',
      },
    },
  },
}];

// ─── NORMALIZAR POSTULANTES (desde postulantes.csv) ───────────────────────
// Columnas esperadas: cedula; apellidos; nombres; fecha_nacimiento; cedula_busqueda (opcional)
const cfg = $('Configuración').first().json;

const sinTildes = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '');
const limpio = s => sinTildes(s).toUpperCase().replace(/[^A-Z0-9Ñ ]/g, ' ').replace(/\s+/g, ' ').trim();
const soloDigitos = s => String(s ?? '').replace(/\D/g, '');

function cedulaValida(c) {
  if (!/^\d{10}$/.test(c)) return false;
  const prov = +c.slice(0, 2);
  if (!((prov >= 1 && prov <= 24) || prov === 30)) return false;
  if (+c[2] >= 6) return false;
  const coef = [2, 1, 2, 1, 2, 1, 2, 1, 2];
  let suma = 0;
  for (let i = 0; i < 9; i++) { let v = +c[i] * coef[i]; if (v > 9) v -= 9; suma += v; }
  return ((10 - (suma % 10)) % 10) === +c[9];
}

// Acepta encabezados con mayúsculas/tildes/espacios
const campo = (row, ...claves) => {
  for (const [k, v] of Object.entries(row)) {
    const kk = limpio(k).replace(/ /g, '_');
    if (claves.includes(kk) && String(v ?? '').trim() !== '') return String(v).trim();
  }
  return '';
};

const salida = [];
for (const it of $input.all()) {
  const r = it.json;
  let cedula = soloDigitos(campo(r, 'CEDULA', 'NUMERO_DE_CEDULA', 'IDENTIFICACION'));
  if (!cedula) continue;                       // fila vacía
  if (cedula.length === 9) cedula = '0' + cedula; // Excel suele quitar el 0 inicial

  const apellidos = limpio(campo(r, 'APELLIDOS'));
  const nombres = limpio(campo(r, 'NOMBRES'));
  const nombreCompleto = limpio(campo(r, 'NOMBRES_COMPLETOS', 'NOMBRE_COMPLETO')) || [apellidos, nombres].filter(Boolean).join(' ');
  const busqueda = soloDigitos(campo(r, 'CEDULA_BUSQUEDA', 'CEDULA_DE_BUSQUEDA'));

  const obs = [];
  if (!cedulaValida(cedula)) obs.push(`La cédula ${cedula} no supera la validación de dígito verificador (módulo 10): revisar el número`);
  if (!nombreCompleto) obs.push('No se proporcionaron nombres: se intentarán tomar del certificado de antecedentes');

  salida.push({
    json: {
      cedula,
      cedula_busqueda: busqueda && busqueda !== cedula ? busqueda : '',
      apellidos,
      nombres,
      nombre_completo: nombreCompleto,
      fecha_nacimiento: campo(r, 'FECHA_NACIMIENTO', 'FECHA_DE_NACIMIENTO'),
      ruta_entrada: `${cfg.BASE_DIR}/entrada/${cedula}`,
      ruta_salida: `${cfg.BASE_DIR}/salida`,
      observaciones_entrada: obs,
    },
  });
}

if (!salida.length) throw new Error('postulantes.csv no tiene filas con cédula');
return salida;

// ─── CLASIFICAR, VALIDAR Y PREPARAR PÁGINAS ───────────────────────────────
// Entrada: un ítem por archivo de entrada/<cedula>/ (binario "data" + texto extraído del PDF).
// Salida: solo las páginas que hay que generar en HTML→PDF (portada, pendientes, foto de cédula).
// La portada lleva en json.expediente el estado completo de los 10 documentos.
const cfg = $('Configuración').first().json;
const p = { ...$('Postulante actual').first().json };
const items = $input.all();
const DIA = 86400000;
const hoy = new Date(cfg.FECHA_PROCESO + 'T12:00:00Z');

// ── utilidades ──
const N = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[ \t ]+/g, ' ');
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fmt = d => (d ? d.toISOString().slice(0, 10).split('-').reverse().join('/') : '—');
const b64 = s => Buffer.from(s, 'utf8').toString('base64');

function cedulaValida(c) {
  if (!/^\d{10}$/.test(c)) return false;
  const prov = +c.slice(0, 2);
  if (!((prov >= 1 && prov <= 24) || prov === 30) || +c[2] >= 6) return false;
  const coef = [2, 1, 2, 1, 2, 1, 2, 1, 2];
  let s = 0;
  for (let i = 0; i < 9; i++) { let v = +c[i] * coef[i]; if (v > 9) v -= 9; s += v; }
  return ((10 - (s % 10)) % 10) === +c[9];
}
const contieneCedula = (t, c) => !!c && new RegExp(`(^|\\D)${c.slice(0, 9)}[- ]?${c[9]}(\\D|$)`).test(t);
const otrasCedulas = (t, propias) => [...new Set((t.match(/(?<!\d)\d{9}-?\d(?!\d)/g) || []).map(x => x.replace('-', '')))]
  .filter(x => cedulaValida(x) && !propias.includes(x));

const MESES = { ENERO: 1, FEBRERO: 2, MARZO: 3, ABRIL: 4, MAYO: 5, JUNIO: 6, JULIO: 7, AGOSTO: 8, SEPTIEMBRE: 9, SETIEMBRE: 9, OCTUBRE: 10, NOVIEMBRE: 11, DICIEMBRE: 12 };
function fechasEn(t) {
  const out = [];
  const add = (y, m, d, idx) => {
    y = +y; m = +m; d = +d;
    if (y < 1950 || y > 2100 || m < 1 || m > 12 || d < 1 || d > 31) return;
    const f = new Date(Date.UTC(y, m - 1, d, 12));
    if (f.getUTCDate() === d) out.push({ f, idx });
  };
  let m;
  const r1 = /(?<!\d)(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})(?!\d)/g; while ((m = r1.exec(t))) add(m[3], m[2], m[1], m.index);
  const r2 = /(?<!\d)(\d{4})[\/\-.](\d{1,2})[\/\-.](\d{1,2})(?!\d)/g; while ((m = r2.exec(t))) add(m[1], m[2], m[3], m.index);
  const r3 = new RegExp(`(?<!\\d)(\\d{1,2})\\s*(?:DE\\s+)?(${Object.keys(MESES).join('|')})\\s*(?:DE(?:L)?\\s+)?(\\d{4})`, 'g');
  while ((m = r3.exec(t))) add(m[3], MESES[m[2]], m[1], m.index);
  return out.sort((a, b) => a.idx - b.idx);
}
function fechaEmision(t) {
  const fs = fechasEn(t);
  if (!fs.length) return null;
  const nac = fechasEn(N(p.fecha_nacimiento || ''))[0]?.f?.getTime();
  const utiles = fs.filter(x => x.f.getTime() !== nac && x.f.getUTCFullYear() >= hoy.getUTCFullYear() - 3);
  const etiqueta = /FECHA\s*(?:Y\s*HORA\s*)?(?:DE\s*)?(?:EMISION|EXPEDICION|GENERACION|IMPRESION|CONSULTA|ELABORACION|EMITIDO)|EMITIDO\s*(?:EL)?|GENERADO\s*(?:EL)?|EXPEDIDO\s*(?:EL)?|IMPRESO\s*(?:EL)?|FECHA(?!\s*(?:DE\s*)?(?:NACIMIENTO|NAC|EXPIRACION|CADUCIDAD|INGRESO|SALIDA|BAJA|ALTA))\s*:?/g;
  let m;
  while ((m = etiqueta.exec(t))) {
    const cerca = utiles.find(x => x.idx >= m.index && x.idx - m.index <= 90);
    if (cerca) return { fecha: cerca.f, metodo: 'etiqueta' };
  }
  // sin etiqueta: la fecha más reciente que no sea futura ni demasiado antigua
  const cand = utiles.filter(x => x.f <= new Date(hoy.getTime() + DIA) && x.f.getUTCFullYear() >= hoy.getUTCFullYear() - 2);
  if (!cand.length) return null;
  return { fecha: cand.reduce((a, b) => (b.f > a.f ? b : a)).f, metodo: 'inferida' };
}

// ── definición de los documentos (orden del PDF) ──
const SLOTS = [
  { orden: 2, clave: 'cedula', titulo: '1. Ser ecuatoriano y mayor de edad (Cédula)', origen: 'manual', imagen: true,
    nombres: ['jpg', 'jpeg', 'png', 'pdf'].map(e => `cedula_${p.cedula}.${e}`) },
  { orden: 3, clave: 'titulo_bachiller', titulo: '2. Título de bachiller', origen: 'portal', nombres: ['titulo_bachiller.pdf', 'bachiller.pdf', 'titulo.pdf'] },
  { orden: 4, clave: 'aptitud_fisica', titulo: '3. Certificado de aptitud física (Centro de salud pública)', origen: 'manual', nombres: ['aptitud_fisica.pdf'] },
  { orden: 5, clave: 'psicologico', titulo: '4. Certificado de prueba de confianza', origen: 'manual', nombres: ['psicologo.pdf'] },
  { orden: 6, clave: 'toxicologico', titulo: '5. Aprobar pruebas toxicológicas', origen: 'manual', nombres: ['toxicologico.pdf'] },
  { orden: 7, clave: 'no_ffaa', titulo: '6. No ser miembro activo de FF.AA.', origen: 'portal', nombres: ['no_ffaa.pdf', 'nofa.pdf'] },
  { orden: 8, clave: 'servidor_publico', titulo: '7. No ser servidor público del ente rector de defensa/seguridad', origen: 'portal', nombres: ['servidor_publico.pdf'] },
  { orden: 9, clave: 'clts', titulo: '8. No haber sido dado de baja por faltas (Exmiembros FF.AA.)', origen: 'portal', nombres: ['tiempo_servicio.pdf', 'clts.pdf'] },
  { orden: 10, clave: 'judiciales', titulo: '9. No tener sentencia condenatoria ejecutoriada', origen: 'portal', nombres: ['judiciales.pdf', 'procesos_judiciales.pdf', 'antecedentes.pdf'] },
];
// Clasificación por contenido para PDFs del portal guardados con otro nombre (p. ej. "certificado (3).pdf")
const PALABRAS = [
  ['antecedentes', t => /ANTECEDENTES PENALES|POSEE ANTECEDENTES/.test(t)],
  ['judiciales', t => /PROCESOS JUDICIALES|SATJE|DEMANDADO\s*\/\s*PROCESADO/.test(t)],
  ['clts', t => /TIEMPO DE SERVICIO/.test(t)],
  ['no_ffaa', t => /FUERZAS ARMADAS/.test(t)],
  ['servidor_publico', t => /SECTOR PUBLICO|DEPENDENCIA LABORAL/.test(t)],
  ['titulo_bachiller', t => /TITULOS? REFRENDADOS?|BACHILLER|MINISTERIO DE EDUCACION/.test(t)],
];

// ── inventario de archivos ──
const archivos = [];
items.forEach((it, i) => {
  const bin = it.binary?.data;
  if (!bin || !bin.fileName) return;
  const nombre = String(bin.fileName);
  const ext = (nombre.split('.').pop() || '').toLowerCase();
  archivos.push({ i, nombre, lower: nombre.toLowerCase(), ext, texto: N(it.json?.text || ''), tieneTexto: !!String(it.json?.text || '').trim() });
});

const asignados = {}; // clave -> [archivos]
const noReconocidos = [];
for (const a of archivos) {
  let slot = SLOTS.find(s => s.nombres.includes(a.lower));
  if (!slot && a.ext === 'pdf' && a.tieneTexto) {
    const hit = PALABRAS.find(([, f]) => f(a.texto));
    if (hit) { slot = SLOTS.find(s => s.clave === hit[0]); a.porContenido = true; }
  }
  if (!slot && /^cedula[_\- ]?.*\.(jpe?g|png)$/.test(a.lower)) {
    slot = SLOTS.find(s => s.clave === 'cedula');
    a.nombreDistinto = true;
  }
  if (slot) (asignados[slot.clave] ||= []).push(a); else noReconocidos.push(a.nombre);
}

// Si no hay nombres en el CSV, intentar leerlos del certificado de antecedentes
if (!p.nombre_completo) {
  const ant = (asignados.antecedentes || [])[0];
  const m = ant?.texto.match(/NOMBRES?(?:\s+Y\s+APELLIDOS)?\s*:?\s*([A-Z ]{6,80}?)\s*(?:\n|TIPO|CEDULA|NUMERO|DOCUMENTO|$)/);
  if (m) { p.nombre_completo = m[1].trim(); p.observaciones_entrada = [...(p.observaciones_entrada || []), `Nombre tomado del certificado de antecedentes: ${p.nombre_completo}`]; }
}
const tokens = [...new Set(N(p.nombre_completo).replace(/[^A-Z ]/g, ' ').split(' ').filter(w => w.length >= 3))];
const cedulasPropias = [p.cedula, p.cedula_busqueda].filter(Boolean);

// ── validación de un archivo contra un documento ──
function evaluar(slot, a) {
  const obs = [], notas = [];
  let rechazo = null;
  const t = a.texto;
  const vig = cfg.VIGENCIA_DIAS[slot.clave];
  let emision = null, vence = null, vigencia = 'no aplica';

  if (a.porContenido) notas.push(`Identificado por contenido (archivo "${a.nombre}")`);
  if (a.nombreDistinto) notas.push(`Nombre de archivo distinto al esperado ("${a.nombre}")`);

  if (slot.imagen) {
    notas.push('Imagen incluida; los datos de la cédula requieren verificación visual (no hay OCR)');
  } else if (!a.tieneTexto) {
    if (slot.origen === 'portal') obs.push('PDF sin texto legible (escaneado o imagen): no se pudo verificar cédula, nombres ni fecha');
    else notas.push('PDF escaneado: sin verificación automática de datos');
  } else {
    const ced = cedulasPropias.some(c => contieneCedula(t, c));
    const ratio = tokens.length ? tokens.filter(w => new RegExp(`\\b${w}\\b`).test(t)).length / tokens.length : null;
    const ajenas = otrasCedulas(t, cedulasPropias);
    const nomTxt = ratio === null ? 'sin nombres para comparar' : `${Math.round(ratio * 100)}% de nombres encontrados`;

    if (!ced && (ajenas.length || (ratio !== null && ratio < 0.5))) {
      rechazo = `El archivo "${a.nombre}" no corresponde al postulante (cédula no encontrada${ajenas.length ? `; aparece otra cédula: ${ajenas.join(', ')}` : ''}; ${nomTxt})`;
    } else if (!ced) {
      (slot.origen === 'portal' ? obs : notas).push(`No aparece la cédula en el documento (${nomTxt})`);
    } else if (ratio === 0) {
      notas.push('La cédula coincide; el documento no muestra los nombres del postulante');
    } else if (ratio !== null && ratio < 0.6) {
      obs.push(`La cédula coincide pero los nombres no coinciden plenamente (${nomTxt})`);
    }

    const fe = fechaEmision(t);
    if (fe) {
      emision = fe.fecha;
      if (fe.metodo === 'inferida') notas.push('Fecha de emisión inferida (el documento no la rotula): confirmar');
      if (emision.getTime() > hoy.getTime() + DIA) obs.push(`La fecha de emisión (${fmt(emision)}) es posterior a hoy`);
    } else if (vig) {
      (slot.origen === 'portal' ? obs : notas).push('No se encontró fecha de emisión en el documento');
    }

    // Alertas de contenido (heurísticas: siempre requieren lectura humana)
    if (slot.clave === 'antecedentes' && (/POSEE ANTECEDENTES\s*:?\s*SI\b/.test(t) ||
        (/REGISTRA ANTECEDENTES/.test(t) && !/NO (REGISTRA|POSEE|TIENE) ANTECEDENTES|POSEE ANTECEDENTES\s*:?\s*NO\b/.test(t))))
      obs.push('ALERTA: el certificado parece indicar antecedentes penales registrados');
    if (slot.clave === 'judiciales' && !/NO SE ENCONTR|NO EXISTEN|SIN RESULTADOS|(^|\D)0 RESULTADOS|NO REGISTRA|NO HAY (DATOS|REGISTROS|PROCESOS)/.test(t))
      obs.push('La consulta lista causas o no indica "sin resultados": revisar si figura como demandado/procesado');
    if (slot.clave === 'no_ffaa' && /PERTENECE/.test(t) && !/NO (PERTENECE|ES MIEMBRO|FORMA PARTE|REGISTRA)/.test(t))
      obs.push('ALERTA: verificar si el certificado indica pertenencia a las FF.AA.');
    if (slot.clave === 'servidor_publico' && /(SI )?MANTIENE RELACION DE DEPENDENCIA|REGISTRA RELACION DE DEPENDENCIA/.test(t) && !/NO (MANTIENE|REGISTRA) (UNA )?RELACION/.test(t))
      obs.push('ALERTA: el certificado parece indicar relación de dependencia vigente con el sector público');
  }

  if (vig && emision) {
    vence = new Date(emision.getTime() + vig * DIA);
    const resta = Math.floor((vence - hoy) / DIA);
    if (resta < 0) { vigencia = 'vencido'; obs.push(`Vencido desde ${fmt(vence)} (vigencia de referencia ${vig} días)`); }
    else if (resta <= cfg.DIAS_POR_VENCER) { vigencia = 'por vencer'; obs.push(`Vence en ${resta} día(s): ${fmt(vence)}`); }
    else vigencia = 'vigente';
  } else if (vig) vigencia = 'sin fecha';

  return { rechazo, obs, notas, emision, vence, vigencia };
}

// ── resultado por documento ──
const slots = [{ orden: 1, clave: 'portada', titulo: 'Portada e índice', origen: 'generado', estado: 'completo', motivo: '', observaciones: [], notas: [], incluir_original: false }];
for (const s of SLOTS) {
  const cands = (asignados[s.clave] || []).map(a => ({ a, ev: evaluar(s, a) }));
  const validos = cands.filter(c => !c.ev.rechazo);
  // Si hay varios válidos: preferir el nombre fijo y luego la emisión más reciente
  validos.sort((x, y) => (s.nombres.includes(y.a.lower) - s.nombres.includes(x.a.lower)) || ((y.ev.emision?.getTime() || 0) - (x.ev.emision?.getTime() || 0)));
  const elegido = validos[0];
  const rechazos = cands.filter(c => c.ev.rechazo).map(c => c.ev.rechazo);
  const portal = cfg.PORTALES[s.clave];
  const r = { orden: s.orden, clave: s.clave, titulo: s.titulo, origen: s.origen, observaciones: [], notas: [], incluir_original: false };

  if (elegido) {
    const { ev, a } = elegido;
    Object.assign(r, {
      archivo: a.nombre, srcIndex: a.i, es_imagen: !!s.imagen && a.ext !== 'pdf', incluir_original: !s.imagen || a.ext === 'pdf',
      fecha_emision: ev.emision ? fmt(ev.emision) : '', vence: ev.vence ? fmt(ev.vence) : '', vigencia: ev.vigencia,
      observaciones: [...ev.obs, ...rechazos], notas: ev.notas,
    });
    if (validos.length > 1) r.notas.push(`Había ${validos.length} archivos para este documento; se usó "${a.nombre}"`);
    r.estado = r.observaciones.length ? 'observación' : 'completo';
    r.motivo = r.observaciones.join(' · ');
  } else {
    r.estado = 'pendiente';
    const base = rechazos.length ? rechazos.join(' · ') : (s.origen === 'portal' ? 'No se encontró el certificado en la carpeta del postulante' : `No se adjuntó ${s.nombres[0]}`);
    r.motivo = base;
    if (portal) {
      r.motivo += `. No se descarga automáticamente: ${portal.bloqueo}`;
      r.accion = `Descargar en ${portal.url} — ${portal.instruccion} — y guardar como ${s.nombres[0]}`;
    } else {
      r.accion = `Escanear/adjuntar el documento y guardarlo como ${s.nombres[0]}`;
    }
    r.vigencia = '';
  }
  slots.push(r);
}

const cuenta = e => slots.filter(s => s.estado === e).length;
const expediente = {
  postulante: p,
  fecha_proceso: cfg.FECHA_PROCESO,
  slots,
  no_reconocidos: noReconocidos,
  totales: { completo: cuenta('completo'), observación: cuenta('observación'), pendiente: cuenta('pendiente') },
};

// ── HTML ──
const CSS = `
@page { size: A4; margin: 16mm 15mm; }
* { box-sizing: border-box; }
body { font-family: "Liberation Sans", Arial, Helvetica, sans-serif; color: #1d232b; font-size: 10.5pt; margin: 0; }
.franja { border-bottom: 3px solid #1d232b; padding-bottom: 10px; margin-bottom: 18px; }
.org { font-size: 9pt; letter-spacing: .08em; text-transform: uppercase; color: #5b6470; }
h1 { font-size: 20pt; margin: 6px 0 2px; }
.sub { color: #5b6470; }
.datos { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; margin: 14px 0 18px; }
.dato { border: 1px solid #d7dbe0; border-radius: 6px; padding: 8px 10px; }
.dato b { display: block; font-size: 8pt; color: #5b6470; text-transform: uppercase; letter-spacing: .05em; font-weight: 600; margin-bottom: 2px; }
.totales { display: flex; gap: 10px; margin-bottom: 14px; }
.tot { flex: 1; border-radius: 6px; padding: 8px 10px; font-weight: 700; }
table { width: 100%; border-collapse: collapse; }
th { text-align: left; font-size: 8pt; text-transform: uppercase; letter-spacing: .05em; color: #5b6470; border-bottom: 1.5px solid #1d232b; padding: 6px 5px; }
td { border-bottom: 1px solid #e3e6ea; padding: 7px 5px; vertical-align: top; }
td.n { width: 22px; color: #5b6470; }
.det { font-size: 8.5pt; color: #5b6470; margin-top: 2px; }
.badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 8.5pt; font-weight: 700; white-space: nowrap; }
.completo { background: #e3f2e8; color: #1e6b3a; }
.observación { background: #fdf0d9; color: #8a5a00; }
.pendiente { background: #fbe3e1; color: #9b2c22; }
.nota { margin-top: 16px; font-size: 8.5pt; color: #5b6470; border-top: 1px solid #e3e6ea; padding-top: 8px; }
.ph { margin-top: 70px; border: 2px dashed #c9cfd6; border-radius: 10px; padding: 34px 32px; }
.ph h2 { margin: 8px 0 14px; font-size: 18pt; }
.ph p { line-height: 1.5; }
.foto { text-align: center; margin-top: 10px; }
.foto img { max-width: 100%; max-height: 225mm; object-fit: contain; border: 1px solid #d7dbe0; }
`;
const encabezado = `<div class="franja"><div class="org">${esc(cfg.ORGANIZACION)}</div>
  <div class="sub">${esc(p.nombre_completo || 'Postulante sin nombre registrado')} · C.I. ${esc(p.cedula)}</div></div>`;
const pagina = (cuerpo, titulo) => `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>${esc(titulo)}</title><style>${CSS}</style></head><body>${cuerpo}</body></html>`;

const filas = slots.map(s => `<tr><td class="n">${s.orden}</td><td><b>${esc(s.titulo)}</b>
  <div class="det">${s.archivo ? `Archivo: ${esc(s.archivo)}` : ''}${s.fecha_emision ? ` · Emisión: ${s.fecha_emision}` : ''}${s.vence ? ` · Vence: ${s.vence}` : ''}</div>
  ${s.motivo ? `<div class="det">${esc(s.motivo)}</div>` : ''}${s.accion ? `<div class="det"><i>${esc(s.accion)}</i></div>` : ''}</td>
  <td><span class="badge ${s.estado}">${s.estado.toUpperCase()}</span></td></tr>`).join('');

const extras = [...(p.observaciones_entrada || []), ...(noReconocidos.length ? [`Archivos no reconocidos (no incluidos): ${noReconocidos.join(', ')}`] : [])];
const portadaHtml = pagina(`
  <div class="franja"><div class="org">${esc(cfg.ORGANIZACION)}</div>
  <h1>${esc(p.nombre_completo || 'Postulante sin nombre registrado')}</h1>
  <div class="sub">Expediente compilado el ${fmt(hoy)}</div></div>
  <div class="datos">
    <div class="dato"><b>Cédula</b>${esc(p.cedula)}</div>
    <div class="dato"><b>Fecha de nacimiento</b>${esc(p.fecha_nacimiento || '—')}</div>
    <div class="dato"><b>Documentos</b>${expediente.totales.completo} de 11 completos</div>
  </div>
  <div class="totales">
    <div class="tot completo">${expediente.totales.completo} completos</div>
    <div class="tot observación">${expediente.totales['observación']} con observación</div>
    <div class="tot pendiente">${expediente.totales.pendiente} pendientes</div>
  </div>
  <table><thead><tr><th>#</th><th>Documento</th><th>Estado</th></tr></thead><tbody>${filas}</tbody></table>
  ${extras.length ? `<div class="nota"><b>Observaciones generales:</b> ${extras.map(esc).join(' · ')}</div>` : ''}
  <div class="nota">Validación automática por coincidencia de cédula, nombres y fecha de emisión. Las vigencias son valores de referencia configurables.
  Los estados "observación" y las alertas de contenido requieren revisión humana antes de aprobar al postulante.</div>`, 'Portada');

const salida = [];
const html = (orden, clave, tipo, contenido, extra = {}) => salida.push({
  json: { tipo, orden, clave, ...extra },
  binary: { index: { data: b64(contenido), mimeType: 'text/html', fileName: 'index.html', fileExtension: 'html' } },
});

html(1, 'portada', 'portada', portadaHtml, { expediente });

for (const s of slots.slice(1)) {
  if (s.estado === 'pendiente') {
    html(s.orden, s.clave, 'pendiente', pagina(`${encabezado}<div class="ph">
      <span class="badge pendiente">DOCUMENTO ${s.orden} · PENDIENTE</span>
      <h2>${esc(s.titulo)}</h2>
      <p><b>Motivo:</b> ${esc(s.motivo)}</p>
      ${s.accion ? `<p><b>Acción:</b> ${esc(s.accion)}</p>` : ''}
      <p class="det">Página de reserva generada el ${fmt(hoy)}. Sustitúyala volviendo a procesar el expediente cuando el documento esté disponible.</p>
    </div>`, s.titulo));
  } else if (s.es_imagen) {
    const bin = items[s.srcIndex].binary.data;
    const buf = await this.helpers.getBinaryDataBuffer(s.srcIndex, 'data');
    const mime = bin.mimeType || (s.archivo.toLowerCase().endsWith('png') ? 'image/png' : 'image/jpeg');
    html(s.orden, s.clave, 'imagen', pagina(`${encabezado}
      <div class="org">Documento ${s.orden} · ${esc(s.titulo)}</div>
      <div class="foto"><img src="data:${mime};base64,${buf.toString('base64')}" alt="Cédula"></div>`, s.titulo));
  }
}
return salida;

// ─── ENSAMBLAR LOS 10 PDF EN ORDEN ────────────────────────────────────────
// Une las páginas generadas por Gotenberg (portada, pendientes, foto) con los PDF originales.
// Gotenberg une los archivos en orden alfabético: 01_... a 10_...
const generados = $input.all();                           // salida de "Gotenberg: HTML a PDF"
const metas = $('Clasificar y validar').all();            // mismo orden que lo enviado a Gotenberg
const fuentes = $('Combinar archivo y texto').all();      // PDF originales
const exp = metas.find(m => m.json.tipo === 'portada').json.expediente;
const dos = n => String(n).padStart(2, '0');

const binary = {};
const errores = [];
metas.forEach((m, i) => {
  const b = generados[i]?.binary?.data;
  if (!b) { errores.push(`No se generó la página ${m.json.orden} (${m.json.clave}): ${generados[i]?.json?.error?.message || generados[i]?.json?.error || 'sin respuesta del servicio PDF'}`); return; }
  binary[`f${dos(m.json.orden)}`] = { ...b, fileName: `${dos(m.json.orden)}_${m.json.clave}.pdf`, mimeType: 'application/pdf', fileExtension: 'pdf' };
});
for (const s of exp.slots.filter(s => s.incluir_original)) {
  const b = fuentes[s.srcIndex]?.binary?.data;
  if (!b) { errores.push(`No se pudo leer el original de ${s.titulo}`); continue; }
  binary[`f${dos(s.orden)}`] = { ...b, fileName: `${dos(s.orden)}_${s.clave}.pdf`, mimeType: 'application/pdf', fileExtension: 'pdf' };
}

const faltan = Array.from({ length: 11 }, (_, k) => `f${dos(k + 1)}`).filter(k => !binary[k]);
return [{ json: { expediente: exp, errores_ensamblaje: errores, partes_faltantes: faltan }, binary }];

// ─── NOMBRAR EL PDF Y REDACTAR EL RESUMEN DEL POSTULANTE ──────────────────
const ens = $('Ensamblar expediente').first().json;
const exp = ens.expediente;
const p = exp.postulante;
const pdf = $input.first().binary?.data;
const errorUnion = $input.first().json?.error;

const slug = String(p.nombre_completo || 'SIN_NOMBRE').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_|_$/g, '');
const nombreArchivo = `${p.cedula}_${slug}.pdf`;

const problemas = [...ens.errores_ensamblaje];
if (ens.partes_faltantes.length) problemas.push(`Partes sin generar: ${ens.partes_faltantes.join(', ')}`);
if (!pdf) problemas.push(`No se pudo unir el PDF: ${errorUnion?.message || errorUnion || 'el servicio Gotenberg no devolvió archivo'} (revise si algún PDF original está protegido con contraseña o dañado)`);

const docs = exp.slots;
const linea = s => `- **${s.orden}. ${s.titulo}**${s.archivo ? ` — \`${s.archivo}\`` : ''}${s.fecha_emision ? ` — emisión ${s.fecha_emision}` : ''}${s.vence ? `, vence ${s.vence} (${s.vigencia})` : ''}`;
const incl = docs.filter(s => s.estado !== 'pendiente');
const pend = docs.filter(s => s.estado === 'pendiente');
const obs = docs.filter(s => s.estado === 'observación');
const notas = docs.filter(s => s.notas?.length);

const md = [
  `# Expediente ${p.cedula} — ${p.nombre_completo || 'sin nombre'}`,
  ``,
  `Procesado: ${exp.fecha_proceso} · Archivo: ${pdf ? nombreArchivo : 'NO GENERADO'} · ${exp.totales.completo} completos, ${exp.totales['observación']} con observación, ${exp.totales.pendiente} pendientes`,
  ``,
  `## Documentos incluidos`,
  ...(incl.length ? incl.map(s => `${linea(s)} — ${s.estado.toUpperCase()}`) : ['- Ninguno']),
  ``,
  `## Pendientes o no encontrados`,
  ...(pend.length ? pend.map(s => `${linea(s)}\n  - Motivo: ${s.motivo}${s.accion ? `\n  - Acción: ${s.accion}` : ''}`) : ['- Ninguno']),
  ``,
  `## Discrepancias y alertas`,
  ...(obs.length || p.observaciones_entrada?.length || exp.no_reconocidos.length
    ? [...obs.map(s => `- **${s.titulo}:** ${s.observaciones.join(' · ')}`),
       ...(p.observaciones_entrada || []).map(o => `- ${o}`),
       ...(exp.no_reconocidos.length ? [`- Archivos no reconocidos (no incluidos): ${exp.no_reconocidos.join(', ')}`] : [])]
    : ['- Ninguna detectada']),
  ``,
  ...(notas.length ? [`## Notas de verificación`, ...notas.map(s => `- ${s.titulo}: ${s.notas.join(' · ')}`), ``] : []),
  ...(problemas.length ? [`## Errores técnicos`, ...problemas.map(x => `- ${x}`), ``] : []),
  `## Límites de la automatización`,
  `Los 5 certificados oficiales no se descargan automáticamente porque cada portal usa un control anti-automatización (captcha de imagen, reCAPTCHA, pregunta de seguridad o capa anti-bots). El flujo no intenta eludirlos: el operador los descarga y n8n valida, fecha, ordena y consolida.`,
].join('\n');

const estados = Object.fromEntries(docs.map(s => [s.clave, s.estado]));
const registro = {
  cedula: p.cedula,
  postulante: p.nombre_completo || '',
  archivo: pdf ? nombreArchivo : '',
  pdf_generado: !!pdf,
  estados,
  completos: exp.totales.completo,
  pendientes: pend.map(s => `${s.orden}. ${s.titulo}`),
  observaciones: [...obs.map(s => `${s.orden}. ${s.titulo}: ${s.observaciones.join(' · ')}`), ...(p.observaciones_entrada || []), ...problemas],
};

const binary = { resumen: { data: Buffer.from(md, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName: `${p.cedula}_${slug}_resumen.md`, fileExtension: 'md' } };
if (pdf) binary.pdf = { ...pdf, fileName: nombreArchivo, mimeType: 'application/pdf', fileExtension: 'pdf' };

return [{
  json: { ...registro, ruta_salida: p.ruta_salida, nombre_resumen: binary.resumen.fileName, registro },
  binary,
}];

// ─── TABLA DE CONTROL DEL LOTE ────────────────────────────────────────────
const cfg = $('Configuración').first().json;
const regs = $input.all().map(i => i.json.registro || i.json).filter(r => r && r.cedula);

const COLS = [
  ['portada', '1. Portada'], ['antecedentes', '2. Antecedentes penales'], ['judiciales', '3. Procesos judiciales'],
  ['no_ffaa', '4. No FF.AA.'], ['clts', '5. Tiempo de servicio'], ['servidor_publico', '6. Servidor público'],
  ['titulo_bachiller', '7. Título bachiller'], ['psicologico', '8. Test de confianza'], ['aptitud_fisica', '9. Aptitud física'], ['toxicologico', '10. Toxicológico'],
  ['cedula', '11. Cédula'],
];
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const csvCell = s => `"${String(s ?? '').replace(/"/g, '""')}"`;

// CSV con ';' y BOM para que Excel (configuración regional Ecuador) lo abra en columnas
const encab = ['Cédula', 'Postulante', ...COLS.map(c => c[1]), 'Completos', 'Archivo PDF', 'Pendientes', 'Observaciones'];
const filasCsv = regs.map(r => [r.cedula, r.postulante, ...COLS.map(([k]) => r.estados?.[k] || ''), `${r.completos}/10`,
  r.archivo || 'NO GENERADO', r.pendientes.join(' | '), r.observaciones.join(' | ')]);
const csv = '﻿' + [encab, ...filasCsv].map(f => f.map(csvCell).join(';')).join('\r\n');

const color = { 'completo': '#e3f2e8;color:#1e6b3a', 'observación': '#fdf0d9;color:#8a5a00', 'pendiente': '#fbe3e1;color:#9b2c22' };
const total = regs.length;
const listos = regs.filter(r => r.completos === 10).length;
const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Control de expedientes ${cfg.FECHA_PROCESO}</title>
<style>body{font-family:Arial,Helvetica,sans-serif;color:#1d232b;margin:24px;font-size:13px}h1{font-size:20px;margin:0 0 4px}
.sub{color:#5b6470;margin-bottom:16px}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #e3e6ea;padding:6px 6px;text-align:left;vertical-align:top}
th{font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:#5b6470;border-bottom:2px solid #1d232b}
.b{display:inline-block;padding:2px 7px;border-radius:9px;font-size:11px;font-weight:700;white-space:nowrap}.det{font-size:11.5px;color:#5b6470;max-width:380px}</style></head><body>
<h1>Tabla de control — expedientes de reclutamiento</h1>
<div class="sub">Lote procesado el ${cfg.FECHA_PROCESO} · ${total} postulante(s) · ${listos} con los 10 documentos completos</div>
<table><thead><tr><th>Cédula</th><th>Postulante</th>${COLS.map(c => `<th>${esc(c[1])}</th>`).join('')}<th>Archivo</th><th>Pendientes / observaciones</th></tr></thead><tbody>
${regs.map(r => `<tr><td>${esc(r.cedula)}</td><td>${esc(r.postulante)}</td>${COLS.map(([k]) => { const e = r.estados?.[k] || ''; return `<td><span class="b" style="background:${color[e] || '#eee'}">${esc(e)}</span></td>`; }).join('')}
<td>${esc(r.archivo || 'NO GENERADO')}</td><td class="det">${[...r.pendientes.map(x => 'Pendiente: ' + x), ...r.observaciones].map(esc).join('<br>')}</td></tr>`).join('\n')}
</tbody></table></body></html>`;

const md = [
  `# Resumen del lote ${cfg.FECHA_PROCESO}`, '',
  `- Postulantes procesados: ${total}`,
  `- Expedientes con los 10 documentos completos: ${listos}`,
  `- PDF no generados por error técnico: ${regs.filter(r => !r.pdf_generado).length}`, '',
  '| Cédula | Postulante | Completos | Pendientes | Observaciones |', '|---|---|---|---|---|',
  ...regs.map(r => `| ${r.cedula} | ${r.postulante} | ${r.completos}/10 | ${r.pendientes.length} | ${r.observaciones.length} |`),
].join('\n');

const bin = (txt, mime, name) => ({ data: Buffer.from(txt, 'utf8').toString('base64'), mimeType: mime, fileName: name });
const sello = cfg.FECHA_PROCESO.replace(/-/g, '');
return [{
  json: { ruta: `${cfg.BASE_DIR}/salida`, postulantes: total, completos: listos, archivo_csv: `control_lote_${sello}.csv`, archivo_html: `control_lote_${sello}.html`, archivo_md: `resumen_lote_${sello}.md` },
  binary: {
    csv: bin(csv, 'text/csv', `control_lote_${sello}.csv`),
    html: bin(html, 'text/html', `control_lote_${sello}.html`),
    md: bin(md, 'text/markdown', `resumen_lote_${sello}.md`),
  },
}];
